# Try rotating and see if any rotation produces a nice pattern
def rotate(grid, k):
    """Rotate grid 90*k degrees clockwise"""
    if k % 4 == 0:
        return grid.copy()
    elif k % 4 == 1:
        return [list(col)[::-1] for col in zip(*grid)]
    elif k % 4 == 2:
        return [row[::-1] for row in reversed(grid)]
    else:
        return [row[::-1] for row in zip(*reversed(grid))]

