# Let me try cellular automaton-style thinking
# What if next state depends on neighbors?

def get_neighbors(r, c):
    """Get surrounding cell values"""
    n_cols = len(grid[0])
    total = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < n_cols:
                total.append(grid[nr][nc])
    return total

# Check neighbor counts for each 0 cell
print("Neighbors for 0 cells:")
for r in range(8):
    for c in range(3):
        if grid[r][c] == 0:
            neighs = get_neighbors(r, c)
            print(f"  ( {r},{c} ): neighbors = {neighs}, count_9s = {sum(neighs)}, count_0s = {len(neighs)-sum(neighs)}")

